// F23 verification footer (plan A12): which festival dates have been checked against Drik Panchang. The table
// data/verified-dates.json is generated by scripts/build-verified-dates.ts from the fetched reference pages; a
// festival-year counts as verified ONLY when the engine's date at the reference city equalled Drik's AND the date
// the app computed for the user's place is that same date. Everything else is "not yet verified" (honest).
import verifiedJson from '../../data/verified-dates.json';
import { type Tradition } from '../panchang/astro';

export interface FestivalVerification {
  source: 'drikpanchang';
  /** Fetch date of the reference page, YYYY-MM-DD. */
  fetchedAt: string;
  /** Reference city id (delhi / chennai). */
  city: string;
  date: string;
}

interface VerifiedTable {
  generatedAt: string;
  entries: Record<string, FestivalVerification>;
}

const TABLE = verifiedJson as unknown as VerifiedTable;

/** When the generated table was built (shown nowhere; kept for the verification file). */
export const VERIFIED_DATES_GENERATED_AT: string = TABLE.generatedAt;

/** Number of verified slug-year-tradition dates in the table. */
export function verifiedFestivalCount(): number {
  return Object.keys(TABLE.entries).length;
}

/** The verification record for a festival occurrence, or null when that exact date was never checked. */
export function festivalVerification(slug: string, year: number, tradition: Tradition, date: string): FestivalVerification | null {
  return TABLE.entries[`${slug}|${year}|${tradition}|${date}`] ?? null;
}
